def choose_part_action(player, part, blocked):
    if player == part:
        return "pick"
    if part[0] > player[0] and "right" not in blocked:
        return "right"
    if part[0] < player[0] and "left" not in blocked:
        return "left"
    if part[1] > player[1] and "down" not in blocked:
        return "down"
    if part[1] < player[1] and "up" not in blocked:
        return "up"
    return "wait"
